import{_ as e,o as t,c as s,a2 as i}from"./chunks/framework.76ZGnlPi.js";const u=JSON.parse('{"title":"Cache Refresh","description":"","frontmatter":{},"headers":[],"relativePath":"admin/ota/cache-status.md","filePath":"admin/ota/cache-status.md"}'),n={name:"admin/ota/cache-status.md"};function o(r,a,l,h,c,d){return t(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="cache-refresh" tabindex="-1">Cache Refresh <a class="header-anchor" href="#cache-refresh" aria-label="Permalink to &quot;Cache Refresh&quot;">​</a></h1><p>This guide explains how administrators can manually refresh the train availability cache for optimal performance.</p><hr><h2 id="quick-overview" tabindex="-1">Quick Overview <a class="header-anchor" href="#quick-overview" aria-label="Permalink to &quot;Quick Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th></tr></thead><tbody><tr><td><strong>Purpose</strong></td><td>Invalidate and re-warm the station/route + train availability cache</td></tr><tr><td><strong>Access</strong></td><td>Admin only</td></tr><tr><td><strong>Scope</strong></td><td>Affects availability-range endpoint performance</td></tr></tbody></table><hr><h2 id="how-cache-works" tabindex="-1">How Cache Works <a class="header-anchor" href="#how-cache-works" aria-label="Permalink to &quot;How Cache Works&quot;">​</a></h2><h3 id="cache-architecture" tabindex="-1">Cache Architecture <a class="header-anchor" href="#cache-architecture" aria-label="Permalink to &quot;Cache Architecture&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────┐     ┌──────────────────┐     ┌─────────────┐</span></span>
<span class="line"><span>│     Client      │────▶│  Availability    │────▶│ Redis Cache │</span></span>
<span class="line"><span>│                 │     │  Range Endpoint  │     │             │</span></span>
<span class="line"><span>└─────────────────┘     └──────────────────┘     └─────────────┘</span></span>
<span class="line"><span>                               │                        │</span></span>
<span class="line"><span>                               │ (cache miss)           │ (hit)</span></span>
<span class="line"><span>                               ▼                        ▼</span></span>
<span class="line"><span>                        ┌──────────────┐        ┌─────────────┐</span></span>
<span class="line"><span>                        │   OTA API    │        │   Response  │</span></span>
<span class="line"><span>                        │ (per date)   │        │             │</span></span>
<span class="line"><span>                        └──────────────┘        └─────────────┘</span></span></code></pre></div><h3 id="cache-key-format" tabindex="-1">Cache Key Format <a class="header-anchor" href="#cache-key-format" aria-label="Permalink to &quot;Cache Key Format&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>train_availability:{origin}:{destination}:{date}</span></span></code></pre></div><p>Example: <code>train_availability:MKX:DMX:2026-02-15</code></p><h3 id="cache-warming" tabindex="-1">Cache Warming <a class="header-anchor" href="#cache-warming" aria-label="Permalink to &quot;Cache Warming&quot;">​</a></h3><p>The system automatically pre-warms cache for ALL available routes:</p><ol><li><strong>Schedule</strong>: Every 30 minutes (configurable via <code>TRAIN_AVAILABILITY_CACHE_INTERVAL_MINUTES</code>)</li><li><strong>Routes</strong>: All routes from the station cache</li><li><strong>Days Ahead</strong>: Next 7 days by default (configurable via <code>TRAIN_AVAILABILITY_CACHE_DAYS_AHEAD</code>)</li></ol><hr><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Cache behavior is controlled via System Configuration:</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>TRAIN_AVAILABILITY_CACHE_INTERVAL_MINUTES</code></td><td>30</td><td>Cache TTL in minutes</td></tr><tr><td><code>TRAIN_AVAILABILITY_CACHE_DAYS_AHEAD</code></td><td>7</td><td>Days to pre-warm (1-30)</td></tr></tbody></table><p>See <a href="./../system-config/">System Configuration</a> for details on updating these values.</p><hr><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><h3 id="refresh-cache" tabindex="-1">Refresh Cache <a class="header-anchor" href="#refresh-cache" aria-label="Permalink to &quot;Refresh Cache&quot;">​</a></h3><p>Manually refresh the station/routes cache and the train availability cache. This is the <strong>only</strong> cache-management endpoint — it both <strong>invalidates</strong> and <strong>re-warms</strong> in a single synchronous call.</p><p><strong>What it does:</strong></p><ol><li>Refreshes the station/routes cache from the OTA API.</li><li>Invalidates the existing availability cache (and the OTA search cache) for every route over the next 7 days.</li><li>Pre-warms the availability cache for all routes by fetching fresh data.</li></ol><p><strong>Endpoint:</strong> <code>POST /api/v1/admin/ota/cache/refresh</code></p><p><strong>Headers:</strong></p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer &lt;admin-token&gt;</span></span></code></pre></div><p><strong>Request Body:</strong> None.</p><p><strong>Response:</strong> <code>200 OK</code></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Cache refresh completed successfully&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;stationCache&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;stationCount&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;routeCount&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">6</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;cacheInvalidated&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">84</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>Response Fields:</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>message</code></td><td>string</td><td>Human-readable result message</td></tr><tr><td><code>stationCache.stationCount</code></td><td>number</td><td>Number of stations in the refreshed station cache</td></tr><tr><td><code>stationCache.routeCount</code></td><td>number</td><td>Number of routes in the refreshed station cache</td></tr><tr><td><code>cacheInvalidated</code></td><td>number</td><td>Total number of availability + search cache keys invalidated before re-warming</td></tr></tbody></table><blockquote><p><strong>Note:</strong> This runs synchronously and may take 30–60 seconds to complete, as it re-fetches fresh availability data for every route across the next 7 days.</p></blockquote><hr><h2 id="common-workflows" tabindex="-1">Common Workflows <a class="header-anchor" href="#common-workflows" aria-label="Permalink to &quot;Common Workflows&quot;">​</a></h2><h3 id="force-a-full-refresh" tabindex="-1">Force a Full Refresh <a class="header-anchor" href="#force-a-full-refresh" aria-label="Permalink to &quot;Force a Full Refresh&quot;">​</a></h3><p>After major pricing changes, schedule updates, or when stale data is suspected:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /api/v1/admin/ota/cache/refresh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer &lt;token&gt;&quot;</span></span></code></pre></div><p>This single call refreshes the station/routes cache, invalidates the existing availability + search caches, and re-warms availability for all routes.</p><p><strong>Use Cases:</strong></p><ul><li>New routes added and need immediate visibility</li><li>Cache issues suspected (stale data)</li><li>After system maintenance or configuration changes</li></ul><hr><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><h3 id="expected-cache-coverage" tabindex="-1">Expected Cache Coverage <a class="header-anchor" href="#expected-cache-coverage" aria-label="Permalink to &quot;Expected Cache Coverage&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Metric</th><th>Expected Value</th></tr></thead><tbody><tr><td>Cache Hit Rate</td><td>&gt; 90%</td></tr><tr><td>Warm Coverage</td><td>100% of routes × days ahead</td></tr><tr><td>Average Response Time</td><td>&lt; 100ms (cached), &lt; 2s (miss)</td></tr></tbody></table><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="issue-low-cache-hit-rate" tabindex="-1">Issue: Low Cache Hit Rate <a class="header-anchor" href="#issue-low-cache-hit-rate" aria-label="Permalink to &quot;Issue: Low Cache Hit Rate&quot;">​</a></h3><p><strong>Symptoms:</strong> Slow availability-range responses</p><p><strong>Causes:</strong></p><ol><li>Cache TTL too short</li><li>Cache warm-up not running</li><li>Redis memory issues</li></ol><p><strong>Solutions:</strong></p><ol><li>Increase <code>TRAIN_AVAILABILITY_CACHE_INTERVAL_MINUTES</code></li><li>Check cron job logs for cache warm-up</li><li>Monitor Redis memory usage</li></ol><h3 id="issue-stale-pricing-data" tabindex="-1">Issue: Stale Pricing Data <a class="header-anchor" href="#issue-stale-pricing-data" aria-label="Permalink to &quot;Issue: Stale Pricing Data&quot;">​</a></h3><p><strong>Symptoms:</strong> Prices don&#39;t match OTA system</p><p><strong>Causes:</strong></p><ol><li>Exchange rate changed but cache not refreshed</li><li>Cache TTL not yet elapsed after a non-pricing change</li></ol><blockquote><p><strong>Note:</strong> Pricing-config changes — <strong>tax rules</strong>, <strong>custom route prices</strong>, and <strong>pricing rules</strong> — now flush the OTA search cache (<code>ota:search:summarized:v1:*</code> and <code>ota:search:raw:v2:*</code>) automatically on every create/update/deactivate, so those changes take effect on the next search. The manual refresh below is only needed for cases that do not auto-flush (e.g. exchange-rate refresh).</p></blockquote><p><strong>Solutions:</strong></p><ol><li>Trigger a full cache refresh via <code>POST /api/v1/admin/ota/cache/refresh</code></li></ol><h3 id="issue-missing-routes-in-cache" tabindex="-1">Issue: Missing Routes in Cache <a class="header-anchor" href="#issue-missing-routes-in-cache" aria-label="Permalink to &quot;Issue: Missing Routes in Cache&quot;">​</a></h3><p><strong>Symptoms:</strong> Some routes always return cache miss</p><p><strong>Causes:</strong></p><ol><li>New routes not in station cache</li><li>Route temporarily unavailable</li></ol><p><strong>Solutions:</strong></p><ol><li>Trigger a full cache refresh to reload the station cache</li><li>Wait for next scheduled warm-up</li></ol><hr><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><p><strong>Peak Periods</strong>: Reduce cache interval to 15 minutes during high-traffic periods (Hajj season, holidays)</p></li><li><p><strong>Off-Peak</strong>: Increase to 60 minutes during low-traffic periods to reduce API load</p></li><li><p><strong>Schedule Changes</strong>: After OTA schedule updates, trigger a manual cache refresh</p></li><li><p><strong>Monitoring</strong>: Check availability responses daily during peak booking periods</p></li></ol><hr><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related Documentation&quot;">​</a></h2><ul><li><a href="./../system-config/">System Configuration</a> - Configure cache settings</li><li><a href="./">OTA Admin Guide</a> - General OTA administration</li><li><a href="/ahlaan-train-docs/customer/routes-calendar/">Routes &amp; Calendar</a> - Customer-facing documentation</li></ul>`,74)])])}const g=e(n,[["render",o]]);export{u as __pageData,g as default};
